"""Real stock controls, blind count recovery and batch traceability."""
from training.lesson_types import Lesson, Step, input_step as fill, select_step as choose, action_step as act

STOCK=("inventory_manager","owner")
COUNTERS=("counter","inventory_manager","owner")
OPS="/inventory-operations"
COUNT="/counts/{count}"


def lesson(id,module,title,roles,situation,concept,example,rule,question,answer,steps,quantity=5,route=OPS,global_access=False):
    if isinstance(steps,Step):steps=(steps,)
    sources=("inventory.py","guided_counts.py") if module=="G" else ("inventory_operations.py","controlled_inventory.py")
    return Lesson(id,module,title,roles,route,"control_"+id,situation,concept,example,rule,
        question,answer,rule+" "+situation,sources,steps,quantity,global_access=global_access)


RESERVE=(
    act('[data-training="reservation-open"]',"Open Reserve stock."),
    choose('#reservation-item',"Choose Chicken (kg).",'{chicken}'),
    choose('#reservation-location',"Choose Training stockroom.",'{store}'),
    fill('#reservation-quantity',"Set aside {quantity} kg for the event.","{quantity}"),
    fill('#reservation-reference-type',"Use event as the reference type.","event"),
    fill('#reservation-reference-id',"Enter {reference} to identify this event.","{reference}"),
    act('[data-training="reservation-save"]',"Check the available amount and reserve the stock.","/reservations"),
)

TRANSFER_FORM=(
    act('[data-training="transfer-create-open"]',"Open Create transfer order."),
    choose('#transfer-source',"Choose Training stockroom as the source.",'{store}'),
    choose('#transfer-destination',"Choose Training kitchen as the destination.",'{kitchen}'),
    choose('[aria-label="Transfer line 1 item"]',"Choose Chicken (kg).",'{chicken}'),
    fill('[aria-label="Transfer line 1 quantity"]',"Request {quantity} kg.","{quantity}"),
    fill('#transfer-notes',"Enter {reference} as the transfer reference in Notes.","{reference}"),
    act('[data-training="transfer-create-save"]',"Save the draft. Stock has not moved yet.","/transfer-orders"),
)

DISPATCH=(
    act('[data-training="transfer-dispatch-training-transfer"]',"Check TRAIN-TRANSFER and choose Dispatch."),
    act('[data-training="confirm"]',"Confirm the physical handover into in-transit control.","/transfer-orders/training-transfer/dispatch"),
)

RECEIVE=(
    act('[data-training="transfer-receive-training-transfer"]',"Open Receive for TRAIN-TRANSFER."),
    fill('[aria-label="Accepted transfer quantity for Chicken (kg)"]',"Accept the {quantity} kg physically received.","{quantity}"),
    act('[data-training="transfer-receipt-save"]',"Check the destination and post this receipt acknowledgement.","/transfer-orders/training-transfer/receive"),
)

COUNT_FIELDS=(
    fill('[aria-label="Counted quantity for Chicken (kg)"]',"Enter the {quantity} kg of chicken you physically counted.","{quantity}"),
    fill('[aria-label="Counted quantity for Guest amenity kit"]',"Enter {secondary_count} individual amenity kits, not boxes.","{secondary_count}"),
)
COUNT_FINISH=(
    act('[data-training="count-save"]',"Save every entered line.","/counts/training-count/entries"),
    act('[data-training="count-submit"]',"Submit the saved count for independent review."),
    act('[data-training="confirm"]',"Confirm submission. Do not change your physical count to match a hidden record.","/counts/training-count/submit"),
)

LOT_FORM=(
    act('[data-training="lot-transaction-open"]',"Open Post lot receipt or issue."),
    choose('#lot-transaction-lot',"Choose TRAIN-LOT, the batch in this situation.",'{lot_id}'),
    choose('#lot-transaction-location',"Choose Training stockroom.",'{store}'),
    choose('#lot-transaction-type',"Choose {lot_action_label}.",'{lot_action}'),
    fill('#lot-transaction-quantity',"Enter {quantity} kg for this batch.","{quantity}"),
    fill('#lot-transaction-cost',"The verified unit cost is PHP 200 per kg.","200"),
    fill('#lot-transaction-reason',"Enter {lot_reason} as the reason.","{lot_reason}"),
    act('[data-training="lot-transaction-save"]',"Check the lot, direction and amount, then post once.","/lot-transactions"),
)

